pre.code:
const hl = () => {
  if (!window.hljs || !$el) return false;
  delete $el.dataset.highlighted;
  window.hljs.highlightElement($el);
  return true;
};
if (!hl()) {
  let t = setInterval(() => { if (hl()) clearInterval(t); }, 50);
}


if (window.hljs && $el) {
  delete $el.dataset.highlighted;
  window.hljs.highlightElement($el);
}
<component_def name="interactive-counter">
  <data_model>
    <state id="counter_value">{data.counter_value}</state>
  </data_model>

  <flex direction="column" gap="12" class="p-5 bg-slate-950">
    <span>State: {data.counter_value}</span>

    <input type="number" bind="data.counter_value" />

    <button>
      <on_click action="MUTATE_STATE" operation="INCREMENT">
        <path>data.counter_value</path>
      </on_click>
      Increment
    </button>
  </flex>
</component_def>

flex.on_mount:
const hl = () => {
    if (!window.hljs || !$el) return false;
    $el.querySelectorAll('pre code').forEach((b) => {
        delete b.dataset.highlighted;
        window.hljs.highlightElement(b);
    });
    return true;
};
if (!hl()) {
    let tries = 0;
    const t = setInterval(() => { tries++; if (hl() || tries > 40) clearInterval(t); }, 50);
}

flex.on_state_change:
setTimeout(() => {
    if (window.hljs && $el) {
        $el.querySelectorAll('pre code').forEach((b) => {
            delete b.dataset.highlighted;
            window.hljs.highlightElement(b);
        });
    }
}, 30);
